from __future__ import annotations
import json
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from urllib.parse import urlparse
from .config import settings
from .db import Database

HTML='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>dexmeme 1USD bot</title><style>:root{font-family:Inter,system-ui,sans-serif;color-scheme:dark;--bg:#0b1020;--panel:#11182b;--line:#26304a;--text:#edf2ff;--muted:#8f9bb5;--good:#55d187;--bad:#ff6b7a;--accent:#7c8cff}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text)}main{max-width:1180px;margin:auto;padding:28px 18px 50px}.top{display:flex;justify-content:space-between;gap:16px;align-items:flex-start;margin-bottom:24px}.brand h1{margin:0;font-size:30px}.brand p{margin:5px 0;color:var(--muted)}.status{display:flex;align-items:center;gap:8px;background:var(--panel);border:1px solid var(--line);padding:9px 13px;border-radius:999px;color:var(--muted);font-size:13px}.dot{width:9px;height:9px;border-radius:50%;background:var(--good)}.grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px}.card{background:var(--panel);border:1px solid var(--line);border-radius:16px;padding:18px}.label{font-size:12px;color:var(--muted);text-transform:uppercase;letter-spacing:.08em}.value{font-size:28px;font-weight:750;margin-top:7px}.sub{font-size:12px;color:var(--muted);margin-top:4px}section{margin-top:18px}.section-title{font-size:17px;font-weight:700;margin:0 0 10px}.panel{background:var(--panel);border:1px solid var(--line);border-radius:16px;overflow:hidden}.bar{height:12px;background:#1b2642;border-radius:999px;overflow:hidden}.fill{height:100%;background:var(--accent);width:0}.table{width:100%;border-collapse:collapse}.table th,.table td{padding:12px 14px;text-align:left;border-bottom:1px solid var(--line);font-size:13px}.table th{color:var(--muted)}.good{color:var(--good)}.bad{color:var(--bad)}.muted{color:var(--muted)}.empty{padding:28px;text-align:center;color:var(--muted)}@media(max-width:850px){.grid{grid-template-columns:repeat(2,minmax(0,1fr))}.top{flex-direction:column}}@media(max-width:520px){.grid{grid-template-columns:1fr}}</style></head><body><main><div class="top"><div class="brand"><h1>dexmeme · 1USD Bot</h1><p>Paper trading · $1 net target · 100+ trades/day research goal</p></div><div class="status"><span class="dot"></span><span id="status">LIVE · refreshing</span></div></div><section class="grid" id="cards"></section><section><h2 class="section-title">Daily progress</h2><div class="panel" style="padding:16px"><div style="display:flex;justify-content:space-between;gap:12px"><span id="goalLabel">0 / 100 trades</span><span class="muted" id="todayPnl">0 SOL today</span></div><div class="bar" style="margin-top:10px"><div class="fill" id="goalFill"></div></div></div></section><section><h2 class="section-title">Open positions</h2><div class="panel" id="positions"></div></section><section><h2 class="section-title">Recent closed trades</h2><div class="panel" id="trades"></div></section><div class="muted" style="text-align:center;margin-top:18px;font-size:12px">Paper mode only · auto-refresh every 3 seconds</div></main><script>const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const num=v=>Number(v||0);function fmt(v,d=6){return num(v).toLocaleString(undefined,{maximumFractionDigits:d})}function render(s){const cards=[['Trades today',`${s.trades_today}/${s.daily_trade_goal}`,'daily goal'],['Target / trade','$'+fmt(s.target_net_usd,2),'net after modeled costs'],['Today P&L',fmt(s.pnl_today_sol)+' SOL','closed trades today'],['Total trades',s.trades_total,'paper trades'],['Win rate',s.win_rate_pct+'%',s.closed_trades+' closed'],['Total P&L',fmt(s.realized_pnl_sol)+' SOL','realized paper P&L'],['Wins',s.wins,'closed winners'],['Losses',s.losses,'closed losers']];document.getElementById('cards').innerHTML=cards.map(c=>`<div class="card"><div class="label">${c[0]}</div><div class="value">${esc(c[1])}</div><div class="sub">${esc(c[2])}</div></div>`).join('');const pct=Math.min(100,(num(s.trades_today)/Math.max(1,num(s.daily_trade_goal)))*100);document.getElementById('goalFill').style.width=pct+'%';document.getElementById('goalLabel').textContent=`${s.trades_today} / ${s.daily_trade_goal} trades`;document.getElementById('todayPnl').textContent=`${fmt(s.pnl_today_sol)} SOL today`;const pos=s.positions||[];document.getElementById('positions').innerHTML=pos.length?`<table class="table"><thead><tr><th>Token</th><th>Entry</th><th>Target</th><th>Size</th></tr></thead><tbody>${pos.map(p=>`<tr><td><b>${esc(p.symbol)}</b><br><span class="muted">${esc(p.token_address)}</span></td><td>$${fmt(p.entry_price,10)}</td><td class="good">+${fmt(p.target_pct,3)}%</td><td>${fmt(p.size_sol,3)} SOL</td></tr>`).join('')}</tbody></table>`:'<div class="empty">No open paper positions.</div>';const trades=s.recent_trades||[];document.getElementById('trades').innerHTML=trades.length?`<table class="table"><thead><tr><th>Token</th><th>Entry → Exit</th><th>P&L</th><th>Reason</th></tr></thead><tbody>${trades.map(t=>`<tr><td><b>${esc(t.symbol)}</b></td><td>$${fmt(t.entry_price,10)} → $${fmt(t.exit_price,10)}</td><td class="${num(t.pnl_pct)>=0?'good':'bad'}">${num(t.pnl_pct)>=0?'+':''}${fmt(t.pnl_pct,3)}%</td><td>${esc(t.exit_reason||'closed')}</td></tr>`).join('')}</tbody></table>`:'<div class="empty">No closed trades yet.</div>';document.getElementById('status').textContent='LIVE · updated now'}async function refresh(){try{const r=await fetch('/api/stats',{cache:'no-store'});if(!r.ok)throw Error();render(await r.json())}catch(e){document.getElementById('status').textContent='OFFLINE · retrying'}}refresh();setInterval(refresh,3000)</script></body></html>'''

class Handler(BaseHTTPRequestHandler):
    def do_GET(self):
        path=urlparse(self.path).path
        if path=='/health':
            self._json({'ok':True,'mode':'paper'}); return
        if path=='/api/stats':
            db=Database(settings.db_path)
            total=int(db.conn.execute('SELECT COUNT(*) FROM positions').fetchone()[0])
            closed=int(db.conn.execute("SELECT COUNT(*) FROM positions WHERE status='closed'").fetchone()[0])
            opens=int(db.conn.execute("SELECT COUNT(*) FROM positions WHERE status='open'").fetchone()[0])
            wins=int(db.conn.execute("SELECT COUNT(*) FROM positions WHERE status='closed' AND pnl_pct>0").fetchone()[0])
            losses=closed-wins
            row=db.conn.execute("SELECT COALESCE(SUM(size_sol*pnl_pct/100),0),COALESCE(AVG(pnl_pct),0) FROM positions WHERE status='closed'").fetchone()
            today=db.conn.execute("SELECT COUNT(*),COALESCE(SUM(size_sol*pnl_pct/100),0) FROM positions WHERE status='closed' AND date(exit_time)=date('now')").fetchone()
            rows=db.conn.execute("SELECT symbol,entry_price,exit_price,pnl_pct,exit_reason FROM positions WHERE status='closed' ORDER BY exit_time DESC LIMIT 15").fetchall()
            body={'mode':'paper','trades_total':total,'closed_trades':closed,'open_positions':opens,'wins':wins,'losses':losses,'win_rate_pct':round(wins/closed*100,2) if closed else 0,'realized_pnl_sol':round(float(row[0]),6),'average_closed_pnl_pct':round(float(row[1]),4),'target_net_usd':settings.target_net_usd,'daily_trade_goal':settings.daily_trade_goal,'trades_today':int(today[0]),'pnl_today_sol':round(float(today[1]),6),'positions':[p.__dict__ for p in db.open_positions()],'recent_trades':[dict(r) for r in rows]}
            self._json(body); return
        if path=='/':
            self._html(HTML); return
        self.send_response(404); self.end_headers()
    def _json(self,obj):
        b=json.dumps(obj).encode(); self.send_response(200); self.send_header('Content-Type','application/json'); self.send_header('Cache-Control','no-store'); self.end_headers(); self.wfile.write(b)
    def _html(self,text):
        b=text.encode(); self.send_response(200); self.send_header('Content-Type','text/html; charset=utf-8'); self.send_header('Cache-Control','no-store'); self.end_headers(); self.wfile.write(b)

def serve(host='0.0.0.0',port=None):
    ThreadingHTTPServer((host,port or settings.port),Handler).serve_forever()
